namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Catalog;
public sealed class AstronomyKnowledgeCatalogArchitectureTests{[Fact]public void KnowledgeCatalog_architecture_files_exist_and_avoid_forbidden_runtime_behaviors(){var root=FindRoot();var dir=Path.Combine(root,"Backend/src/Astronomy.MediaFactory.Core/KnowledgeFoundation/Catalog");Assert.True(Directory.Exists(dir));string[] required=["AstronomyKnowledgeCatalogEntryKind.cs","AstronomyKnowledgeCatalogEntryId.cs","AstronomyKnowledgeCatalogEntry.cs","AstronomyKnowledgeCatalogSnapshot.cs","IAstronomyKnowledgeCatalog.cs","AstronomyKnowledgeCatalog.cs","IAstronomyKnowledgeCatalogBuilder.cs","AstronomyKnowledgeCatalogBuilder.cs","AstronomyKnowledgeCatalogRegistrationExtensions.cs"];foreach(var f in required)Assert.False(string.IsNullOrWhiteSpace(File.ReadAllText(Path.Combine(dir,f))));var all=string.Join('\n',Directory.GetFiles(dir,"*.cs").Select(File.ReadAllText));foreach(var bad in new[]{"DbContext","HttpClient","Controller","BackgroundService","IHostedService","DateTime.Now","DateTime.UtcNow","DateTimeOffset.Now","DateTimeOffset.UtcNow","Activator.CreateInstance","Assembly.GetTypes","AppDomain.CurrentDomain","BuildServiceProvider","SaveChanges","JsonSerializer.Deserialize","InferKnowledge","GenerateKnowledge","PredictEvent","Ephemeris"})Assert.DoesNotContain(bad,all);var typed=Path.Combine(root,"Backend/src/Astronomy.MediaFactory.Core/KnowledgeFoundation/TypedDomains");Assert.DoesNotContain("KnowledgeFoundation.Catalog",string.Join('\n',Directory.GetFiles(typed,"*.cs",SearchOption.AllDirectories).Select(File.ReadAllText)));var tests=Path.Combine(root,"Backend/tests/Astronomy.MediaFactory.Tests/KnowledgeFoundation/Catalog");foreach(var f in new[]{"KnowledgeCatalogFixture.cs","AstronomyKnowledgeCatalogEntryIdTests.cs","AstronomyKnowledgeCatalogEntryTests.cs","AstronomyKnowledgeCatalogSnapshotTests.cs","AstronomyKnowledgeCatalogBuilderTests.cs","AstronomyKnowledgeCatalogTests.cs","AstronomyKnowledgeCatalogRegistrationTests.cs","AstronomyKnowledgeCatalogIntegrationTests.cs","AstronomyKnowledgeCatalogArchitectureTests.cs"})Assert.True(File.Exists(Path.Combine(tests,f)));}static string FindRoot(){var d=new DirectoryInfo(AppContext.BaseDirectory);while(d!=null&&!Directory.Exists(Path.Combine(d.FullName,"Backend")))d=d.Parent;return d!.FullName;}}
